import json
import uuid
from pathlib import Path


class ProviderError(Exception):
    def __init__(self, code, detail):
        super().__init__(detail)
        self.code = code


class Runner:
    def __init__(self, queue_dir, provider, telemetry):
        self.queue_dir = Path(queue_dir)
        self.queue_dir.mkdir(parents=True, exist_ok=True)
        self.provider = provider
        self.telemetry = telemetry

    def _observe(self, run_id, entrypoint, stage, status, **failure):
        fields = {
            "run_id": run_id,
            "entrypoint": entrypoint,
            "stage": stage,
            "status": status,
            **failure,
        }
        # Each optional collector surface must fail independently of business work.
        try:
            self.telemetry.record("batch_run", **fields)
        except Exception:
            pass
        try:
            self.telemetry.save_state("run-" + run_id, **fields)
        except Exception:
            pass

    def _increment(self, name, **labels):
        try:
            self.telemetry.increment(name, **labels)
        except Exception:
            pass

    def _enqueue(self, job, entrypoint):
        run_id = uuid.uuid4().hex
        message = {"run_id": run_id, "job": job, "entrypoint": entrypoint}
        self._observe(run_id, entrypoint, "enqueue", "running")
        try:
            (self.queue_dir / (run_id + ".json")).write_text(json.dumps(message))
        except Exception:
            self._observe(
                run_id, entrypoint, "enqueue", "failed",
                failure_kind="unexpected_error", failure_stage="enqueue",
            )
            self._increment("batch_enqueue_failures", entrypoint=entrypoint)
            raise
        self._observe(run_id, entrypoint, "queued", "queued")
        self._increment("batch_runs_queued", entrypoint=entrypoint)
        return run_id

    def scheduled(self, job):
        return self._enqueue(job, "scheduled")

    def manual(self, job):
        return self._enqueue(job, "manual")

    def execute(self, run_id):
        path = self.queue_dir / (run_id + ".json")
        entrypoint = "unknown"
        stage = "load"
        failure = {}
        self._observe(run_id, entrypoint, stage, "running")
        try:
            message = json.loads(path.read_text())
            if isinstance(message, dict) and message.get("entrypoint") in ("scheduled", "manual"):
                entrypoint = message["entrypoint"]
            job = message["job"]
            stage = "send"
            self._observe(run_id, entrypoint, stage, "running")
            try:
                receipt = self.provider.send(job)
            except ProviderError as error:
                result = {"run_id": run_id, "ok": False, "code": error.code}
                outcome = "provider_error"
                failure = {"failure_kind": outcome, "failure_stage": stage}
                self._observe(run_id, entrypoint, stage, "failed", **failure)
            else:
                result = {"run_id": run_id, "ok": True, "receipt": receipt}
                outcome = "success"
                self._observe(run_id, entrypoint, stage, "succeeded")
            stage = "acknowledge"
            self._observe(run_id, entrypoint, stage, "running", **failure)
            path.unlink()
        except Exception:
            self._observe(
                run_id, entrypoint, stage, "failed",
                failure_kind="unexpected_error", failure_stage=stage,
            )
            self._increment("batch_run_outcomes", entrypoint=entrypoint, outcome="unexpected_error")
            raise
        self._observe(
            run_id, entrypoint, "complete", "succeeded" if outcome == "success" else "failed", **failure,
        )
        self._increment("batch_run_outcomes", entrypoint=entrypoint, outcome=outcome)
        return result

