import json
import uuid
from pathlib import Path


class ProviderError(Exception):
    def __init__(self, code, detail):
        super().__init__(detail)
        self.code = code


class Runner:
    def __init__(self, queue_dir, provider, telemetry):
        self.queue_dir = Path(queue_dir)
        self.queue_dir.mkdir(parents=True, exist_ok=True)
        self.provider = provider
        self.telemetry = telemetry

    def _observe(self, event, context, phase, outcome, failure_class=None):
        fields = {**context, "phase": phase, "outcome": outcome}
        if failure_class is not None:
            fields["failure_class"] = failure_class
        try:
            self.telemetry.record(event, **fields)
        except Exception:
            # This collector is optional; its failure must not change the job.
            pass
        try:
            self.telemetry.save_state("run-" + context["run_id"], **fields)
        except Exception:
            pass

    def _count(self, context, outcome):
        try:
            self.telemetry.increment(
                "batch_execution_outcomes",
                entry_point=context["entry_point"],
                outcome=outcome,
            )
        except Exception:
            pass

    def _enqueue(self, job, entry_point):
        run_id = uuid.uuid4().hex
        message = {"run_id": run_id, "entry_point": entry_point, "job": job}
        (self.queue_dir / (run_id + ".json")).write_text(json.dumps(message))
        self._observe(
            "batch.queued", {"run_id": run_id, "entry_point": entry_point},
            "queued", "pending",
        )
        return run_id

    def scheduled(self, job):
        return self._enqueue(job, "scheduled")

    def manual(self, job):
        return self._enqueue(job, "manual")

    def execute(self, run_id):
        safe_run_id = run_id if (
            isinstance(run_id, str)
            and len(run_id) == 32
            and all(character in "0123456789abcdef" for character in run_id)
        ) else uuid.uuid4().hex
        context = {
            "run_id": safe_run_id,
            "execution_id": uuid.uuid4().hex,
            "entry_point": "unknown",
        }
        phase = "queue_read"
        self._observe("batch.progress", context, phase, "running")
        try:
            path = self.queue_dir / (run_id + ".json")
            message = json.loads(path.read_text())
            entry_point = message.get("entry_point") if isinstance(message, dict) else None
            if entry_point in ("scheduled", "manual"):
                context["entry_point"] = entry_point
            job = message["job"]
            phase = "provider_send"
            self._observe("batch.progress", context, phase, "running")
            failure_class = None
            try:
                receipt = self.provider.send(job)
            except ProviderError as error:
                result = {"run_id": run_id, "ok": False, "code": error.code}
                outcome = "provider_error"
                failure_class = "provider_timeout" if (
                    isinstance(error.code, str) and error.code == "TIMEOUT"
                ) else "provider_error"
            else:
                result = {"run_id": run_id, "ok": True, "receipt": receipt}
                outcome = "success"
            phase = "queue_remove"
            self._observe("batch.progress", context, phase, outcome, failure_class)
            path.unlink()
        except Exception:
            self._observe(
                "batch.execution_finished", context, phase,
                "unexpected_error", "unexpected_error",
            )
            self._count(context, "unexpected_error")
            raise
        self._observe("batch.execution_finished", context, "complete", outcome, failure_class)
        self._count(context, outcome)
        return result

